const i = $.input;
return {
  body: {
    address_from: {
      name: i.fromName,
      street1: i.fromStreet1,
      city: i.fromCity,
      state: i.fromState,
      zip: i.fromZip,
      country: i.fromCountry || 'US'
    },
    address_to: {
      name: i.toName,
      street1: i.toStreet1,
      city: i.toCity,
      state: i.toState,
      zip: i.toZip,
      country: i.toCountry || 'US'
    },
    parcels: [{
      length: i.length,
      width: i.width,
      height: i.height,
      distance_unit: i.distanceUnit || 'in',
      weight: i.weight,
      mass_unit: i.massUnit || 'lb'
    }]
  }
};

const resp = $.steps.createShipment.response || {};
const rates = (resp.rates || []).map(r => ({
  provider: r.provider || '',
  servicelevel: r.servicelevel?.name || r.servicelevel_name || '',
  amount: r.amount || '',
  currency: r.currency || 'USD',
  estimatedDays: r.estimated_days || r.days || null,
  objectId: r.object_id || ''
}));

return {
  shipmentId: resp.object_id || '',
  status: resp.status || '',
  rates,
  rateCount: rates.length,
  from: `${$.input.fromCity}, ${$.input.fromState}`,
  to: `${$.input.toCity}, ${$.input.toState}`,
  summary: resp.object_id ? `Shipment ${resp.object_id} created with ${rates.length} rate${rates.length === 1 ? '' : 's'} available` : 'Failed to create shipment'
};
